describe('Edit Task Functionality', () => {
    beforeEach(() => {
        cy.visit('/tasks'); // Adjust the URL to your application's task page
        cy.get('.task').first().as('firstTask'); // Assuming tasks have a class of 'task'
    });

    it('should edit an existing task successfully', () => {
        cy.get('@firstTask').find('.edit-button').click(); // Assuming edit button has a class of 'edit-button'
        cy.get('.task-edit-input').clear().type('Updated Task Name'); // Assuming input has a class of 'task-edit-input'
        cy.get('.save-button').click(); // Assuming save button has a class of 'save-button'

        cy.get('@firstTask').should('contain', 'Updated Task Name'); // Verify the task name is updated
    });

    it('should show an error message when editing with an empty name', () => {
        cy.get('@firstTask').find('.edit-button').click();
        cy.get('.task-edit-input').clear(); // Clear the input
        cy.get('.save-button').click();

        cy.get('.error-message').should('be.visible').and('contain', 'Task name cannot be empty'); // Verify error message
    });
});
